import csv
with open('outputs/t08_pois_clean.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for i, row in enumerate(reader):
        lat = float(row['latitude'])
        lon = float(row['longitude'])
        if not (-90 <= lat <= 90):
            print(f'Row {i+1}: Invalid latitude {lat}')
        if not (-180 <= lon <= 180):
            print(f'Row {i+1}: Invalid longitude {lon}')
print('Lat/lon validation complete')
